import fs from 'node:fs'

const text = fs.readFileSync('data/learning/i18n.json', 'utf8')
const languages = JSON.parse(text)
const keys = Object.keys(languages.en).sort().join('\n')
for (const [lang, values] of Object.entries(languages)) {
  if (Object.keys(values).sort().join('\n') !== keys || Object.values(values).some((value) => typeof value !== 'string' || !value.trim())) {
    throw new Error(`Incomplete learning UI translations: ${lang}`)
  }
}
fs.writeFileSync('mobile/lib/core/learning_i18n.dart',
  '// Generated by scripts/sync-learning-content.mjs.\n' +
  `const Map<String, Map<String, String>> learningTranslations = ${text.replaceAll('$', '\\$').trim()};\n`)
fs.mkdirSync('mobile/assets/hsk', { recursive: true })
fs.copyFileSync('public/hsk/syllabus-zh.json', 'mobile/assets/hsk/syllabus-zh.json')
